const utils={book_new(){return{SheetNames:[],Sheets:{}}},book_append_sheet(wb,ws,name){wb.SheetNames.push(name);wb.Sheets[name]=ws},json_to_sheet(rows,{header}={}){return{header:header||Object.keys(rows[0]||{}),rows}},aoa_to_sheet(aoa){return{aoa}}};
const cols=['site_id','slot_id','slot_anchor','format_name','width','height','partner_id','partner_name','partner_share','share_basis','share_policy','network_id','account_id','unit_id','loader_code','ad_code','initialization_code','network_priority','timeout_ms','guaranteed','enabled','aesthetic','maximum_visibility','maximum_clicks','maximum_revenue','notes'];
