function rr(site,slot,anchor,partner,name,share,network,account,unit,prio,out='filled',policy='open-yield'){return {site_id:site,slot_id:slot,slot_anchor:anchor,format_name:'wide-skyscraper',width:160,height:600,partner_id:partner,partner_name:name,partner_share:share,share_basis:'confirmed-fills',share_policy:policy,network_id:network,account_id:account,unit_id:unit,loader_code:'',ad_code:ad(`${name} ${network} ${unit}`,out),initialization_code:'',network_priority:prio,timeout_ms:300,guaranteed:network==='house',enabled:true,aesthetic:'on',maximum_visibility:'on',maximum_clicks:'on',maximum_revenue:'on',notes:''};}
