mkdirSync('examples',{recursive:true}); const wb=utils.book_new(); utils.book_append_sheet(wb,utils.aoa_to_sheet([['Ad Runner Iterative Partner Model template'],['A sheet is a human-readable routing table. site_id identifies the website.']]),'_README'); utils.book_append_sheet(wb,utils.aoa_to_sheet([['Iterative Partner Model','IPM routes one slot among partners, then iterates through each Partner Lane.']]),'_TERMS'); utils.book_append_sheet(wb,utils.json_to_sheet([], {header:cols}),'_TEMPLATE'); utils.book_append_sheet(wb,utils.json_to_sheet(shared, {header:cols}),'shared-demo'); utils.book_append_sheet(wb,utils.json_to_sheet(solo, {header:cols}),'solo-demo'); utils.book_append_sheet(wb,utils.json_to_sheet([rr('news.example','leaderboard','top','editorial','Editorial',100,'simulated','news_acct','news_top',100,'filled')], {header:cols}),'extra-site'); writeFileSync('examples/ad-runner-template.xlsx',JSON.stringify(wb,null,2)); console.log('wrote examples/ad-runner-template.xlsx');
